import{_ as a,C as i,o as l,c as u,j as s,a as n,E as r,a2 as o}from"./chunks/framework.BxGh02fV.js";const m=JSON.parse('{"title":"Backlog","description":"","frontmatter":{"title":"Backlog"},"headers":[],"relativePath":"guide/backlog.md","filePath":"guide/backlog.md"}'),g={name:"guide/backlog.md"};function c(d,e,p,h,q,f){const t=i("Capture");return l(),u("div",null,[e[0]||(e[0]=s("h1",{id:"backlog",tabindex:"-1"},[n("Backlog "),s("a",{class:"header-anchor",href:"#backlog","aria-label":'Permalink to "Backlog"'},"​")],-1)),e[1]||(e[1]=s("p",null,[n("Le backlog est l'écran où vous organisez et comprenez le travail. Son arbre a deux racines : "),s("strong",null,"Registre"),n(", le registre des évolutions du produit et ses lots, et "),s("strong",null,"Projet"),n(", qui porte l'historique des sessions et, en dessous, les épics, leurs stories et leurs tâches. Chaque élément de l'arbre a sa propre page, qui dit ce qu'il cadre et ce qu'il contient.")],-1)),r(t,{name:"backlog",alt:"L'écran Backlog sur la racine Projet : la dernière session et l'historique des sessions"}),e[2]||(e[2]=o('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>Portée</strong> (colonne de gauche) : un champ <strong>Rechercher…</strong>, le filtre de <strong>Statut</strong> (<strong>Tous</strong> ou <strong>Masquer terminés</strong>), puis l&#39;arbre : <strong>Registre</strong>, <strong>Projet — Atelier</strong>, et sous lui les épics numérotés, que vous dépliez jusqu&#39;aux stories puis aux tâches. Dès que le projet couvre plus d&#39;une année, un filtre <strong>Millésime</strong> apparaît, et les résultats de recherche sont rangés par année.</li><li><strong>Panneau de droite</strong> : la page de ce qui est sélectionné.</li></ul><h2 id="les-pages" tabindex="-1">Les pages <a class="header-anchor" href="#les-pages" aria-label="Permalink to &quot;Les pages&quot;">​</a></h2><h3 id="projet-—-l-historique-des-sessions" tabindex="-1">Projet — l&#39;historique des sessions <a class="header-anchor" href="#projet-—-l-historique-des-sessions" aria-label="Permalink to &quot;Projet — l&#39;historique des sessions&quot;">​</a></h3><p>La racine <strong>Projet</strong> montre la <strong>Dernière session</strong>, avec son résumé, puis la liste des sessions, la plus récente en tête. La source est indiquée :</p><ul><li><strong>Kessho</strong>, si votre mémoire Kessho connaît ce dépôt : Effortless l&#39;interroge et affiche ses archives de session ;</li><li>sinon <strong>Effortless (ce poste)</strong> : chaque fois qu&#39;un agent travaille sur le projet par le serveur MCP, Effortless enregistre la session (son client, les verbes appelés, les tâches touchées, le nombre de commits), et l&#39;agent peut y écrire un résumé. Ces sessions restent sur votre poste ; elles ne sont pas versionnées.</li></ul><p>Si une source n&#39;a pas pu être lue, la page le dit (« Non lu : … ») et donne la raison au survol.</p><h3 id="registre-—-evolutions-et-lots" tabindex="-1">Registre — évolutions et lots <a class="header-anchor" href="#registre-—-evolutions-et-lots" aria-label="Permalink to &quot;Registre — évolutions et lots&quot;">​</a></h3>',8)),r(t,{name:"backlog-registre",alt:"La racine Registre : le registre des évolutions et l'onglet Lots"}),e[3]||(e[3]=o('<p>La racine <strong>Registre</strong> ouvre deux onglets, <strong>Registre des évolutions</strong> et <strong>Lots</strong>. Le tableau liste chaque évolution : identifiant, <strong>Type</strong> (Anomalie, Amélioration, Fonctionnalité, Découverte, Test), titre, <strong>État</strong>, <strong>Criticité</strong> et <strong>Priorité</strong>. Un clic sur un en-tête de colonne trie le tableau. Au-dessus : <strong>Rechercher (id, titre, détail)…</strong>, les filtres par <strong>Marqueur</strong> et <strong>Masquer Résolu/Retiré</strong>.</p><p>Un clic sur le titre d&#39;une évolution ouvre le tiroir <strong>Détail de l&#39;évolution</strong>.</p><p>L&#39;onglet <strong>Lots</strong> affiche « Lots à graduer » : chaque lot liste ses évolutions dans l&#39;ordre où elles seront graduées.</p><h3 id="epic-—-ce-qu-il-cadre-et-ses-stories" tabindex="-1">Épic — ce qu&#39;il cadre et ses stories <a class="header-anchor" href="#epic-—-ce-qu-il-cadre-et-ses-stories" aria-label="Permalink to &quot;Épic — ce qu&#39;il cadre et ses stories&quot;">​</a></h3>',4)),r(t,{name:"backlog-epic",alt:"La page d'un épic : ce qu'il cadre, puis ses stories"}),e[4]||(e[4]=o('<p>La page d&#39;un épic dit <strong>Ce que l&#39;épic cadre</strong> (sa description), puis liste ses <strong>stories</strong>, chacune avec sa phase et son état ; un clic ouvre la story. En dessous : <strong>Nouvelle story</strong>, <strong>Clôturer l&#39;epic</strong> et les <strong>Drafts</strong> de découpage — des stories candidates, avec leur statut (brouillon, soumis, matérialisé, rejeté).</p><h3 id="story-—-ce-qu-elle-cadre-et-ses-taches" tabindex="-1">Story — ce qu&#39;elle cadre et ses tâches <a class="header-anchor" href="#story-—-ce-qu-elle-cadre-et-ses-taches" aria-label="Permalink to &quot;Story — ce qu&#39;elle cadre et ses tâches&quot;">​</a></h3>',2)),r(t,{name:"backlog-story",alt:"La page d'une story : ce qu'elle cadre, puis ses tâches"}),e[5]||(e[5]=o('<p>La page d&#39;une story indique si elle est la <strong>Story active</strong> ou une <strong>Story inactive</strong>, et combien de tâches sont faites (« 2/5 tâches faites »). Elle dit <strong>Ce que la story cadre</strong> (son objectif, modifiable), puis liste ses <strong>tâches</strong> avec leur état ; un clic ouvre la tâche. En dessous : <strong>Activer</strong>, <strong>Clôturer</strong>, la <strong>Proposition</strong> et le bloc <strong>Reloop</strong>, dont le bouton <strong>Rebobiner</strong> renvoie la story vers une phase antérieure.</p><h3 id="tache-—-ce-qu-il-faut-faire-et-ce-qu-elle-a-produit" tabindex="-1">Tâche — ce qu&#39;il faut faire et ce qu&#39;elle a produit <a class="header-anchor" href="#tache-—-ce-qu-il-faut-faire-et-ce-qu-elle-a-produit" aria-label="Permalink to &quot;Tâche — ce qu&#39;il faut faire et ce qu&#39;elle a produit&quot;">​</a></h3>',2)),r(t,{name:"backlog-tache",alt:"La page d'une tâche : ce qui doit être fait, ce qu'elle a produit, ses commits"}),e[6]||(e[6]=o('<p>La page d&#39;une tâche porte sa référence (par exemple <code>26E2S1T1</code>), son état, sa phase et, si elle est close, sa date (« close le … »), puis trois sections :</p><ul><li><strong>Ce qui doit être fait</strong> : la description de la tâche, modifiable ;</li><li><strong>Ce que la tâche a produit</strong> : son résultat, constaté, modifiable — l&#39;agent le renseigne en clôturant la tâche ;</li><li><strong>Commits de la tâche</strong> : les commits dont le message cite sa référence.</li></ul><p>Le lien en haut de page ramène à sa story.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><ul><li><strong>Créer un épic</strong> : sur la racine Projet, <strong>Nouvel epic</strong> demande une <strong>Zone</strong> et un <strong>Titre</strong> ; la <strong>Description (facultatif)</strong> peut rester vide.</li><li><strong>Créer une story</strong> : sur un épic, <strong>Nouvelle story</strong> demande un <strong>Titre</strong>, et en option un <strong>Slug</strong> et des <strong>Dépendances</strong>.</li><li><strong>Proposer une découpe</strong> : sur un épic, <strong>Draft</strong> ouvre un formulaire (<strong>Titre</strong>, <strong>Résumé</strong>, <strong>Nature</strong> <code>opale</code> ou <code>fix</code>, <strong>Justification (facultatif)</strong>), puis <strong>Créer le draft</strong>. Chaque draft se fait <strong>Éditer</strong>, <strong>Soumettre</strong>, <strong>Valider → Story</strong> (la story apparaît dans l&#39;arbre) ou <strong>Rejeter</strong>.</li><li><strong>Activer et clôturer</strong> : <strong>Activer</strong> fait d&#39;une story la story active ; <strong>Clôturer</strong> exige que toutes ses tâches soient <strong>Terminée</strong> ; <strong>Clôturer l&#39;epic</strong> exige que toutes ses stories soient terminées.</li><li><strong>Proposer et rebobiner</strong> : la <strong>Proposition</strong> se rédige dans sa zone de texte, puis <strong>Enregistrer</strong>, <strong>Valider</strong> ou <strong>Rejeter</strong>. Pour le <strong>Reloop</strong>, choisissez la phase dans « Choisir une phase cible… », puis <strong>Rebobiner</strong> ; si la story n&#39;est pas active, le reloop l&#39;active d&#39;abord, et l&#39;écran le dit.</li><li><strong>Ajouter une évolution</strong> : dans le registre, <strong>Ajouter</strong> demande un type et un titre.</li><li><strong>Trier les évolutions</strong> : dans le tableau, saisissez la <strong>Criticité</strong> (1 Bloquante, 2 Majeure, 3 Mineure) et la <strong>Priorité</strong> ; la valeur s&#39;enregistre quand vous quittez le champ. Une anomalie peut être requalifiée en amélioration, et inversement, par le bouton « → Amélioration » ou « → Anomalie » de sa ligne ; les autres types ne se requalifient pas.</li><li><strong>Marquer ou annuler une évolution</strong> : dans le tiroir <strong>Détail de l&#39;évolution</strong>, <strong>Marquer prêt à graduer</strong> (ou <strong>Retirer le marquage</strong>), et <strong>Annuler</strong>, qui demande un <strong>Motif de l&#39;annulation</strong>.</li><li><strong>Constituer un lot</strong> : cochez des évolutions (<strong>Tout sélectionner</strong>, <strong>Vider la sélection</strong>), puis <strong>Créer un lot avec la sélection</strong>. Dans l&#39;onglet <strong>Lots</strong>, <strong>Nouveau lot</strong> crée un lot vide ; dans un lot, <strong>Monter</strong> et <strong>Descendre</strong> ordonnent les évolutions, <strong>Retirer du lot</strong> en sort une, <strong>Ajouter une évolution</strong> n&#39;en propose que des prêtes à graduer, et <strong>Retirer</strong> supprime le lot après confirmation.</li></ul><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p><code>effortless_epic_start</code> et <code>effortless_story_start</code> créent épics et stories ; <code>effortless_task_update</code> porte aussi le <code>result</code> d&#39;une tâche ; <code>effortless_sessions</code> rend l&#39;historique des sessions que montre la racine Projet, et <code>effortless_session_summary</code> écrit le résumé de la session en cours ; <code>effortless_evolution_add</code> et <code>effortless_evolution_graduate</code> tiennent le registre.</p>',7))])}const _=a(g,[["render",c]]);export{m as __pageData,_ as default};
